Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>
using namespace std;

int read() {
    int x; cin >> x; return x;
}
string readStr() {
    string s; cin >> s; return s;
}

struct Edge {
    int u, v, cap, flow;
};

vector<Edge> edges;
vector<int> g[100000];
int distA[31][31], distB[31][31];
int dx[] = {0, 0, -1, 1};
int dy[] = {1, -1, 0, 0};
int n, t;
string a[30], b[30];
int startX, startY;
int s, t_;
int level[100000], ptr[100000], queueArr[100000];

void addEdge(int u, int v, int cap) {
    edges.push_back({u, v, cap, 0});
    g[u].push_back((int)edges.size() - 1);
    edges.push_back({v, u, 0, 0});
    g[v].push_back((int)edges.size() - 1);
}

bool valid(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < n;
}

void BFS1(int x = 0, int y = 0) {
    queue<pair<int,int>> q;
    q.push({x, y});
    for (int i = 0; i <= 20; ++i)
        for (int j = 0; j <= 20; ++j)
            distA[i][j] = 1e9;
    distA[x][y] = 0;
    while (!q.empty()) {
        auto [cx, cy] = q.front(); q.pop();
        for (int i = 0; i < 4; ++i) {
            int nx = cx + dx[i], ny = cy + dy[i];
            if (valid(nx, ny) && distA[nx][ny] >= 1e9 && b[nx][ny] != 'Y') {
                distA[nx][ny] = distA[cx][cy] + 1;
                q.push({nx, ny});
            }
        }
    }
}

bool bfs() {
    memset(level, -1, sizeof(level));
    int front = 0, back = 0;
    queueArr[back++] = s;
    level[s] = 0;
    while (front < back && level[t_] == -1) {
        int v = queueArr[front++];
        for (int id : g[v]) {
            int to = edges[id].v;
            if (level[to] == -1 && edges[id].flow < edges[id].cap) {
                level[to] = level[v] + 1;
                queueArr[back++] = to;
            }
        }
    }
    return level[t_] != -1;
}

int sendFlow(int v, int flow) {
    if (v == t_) return flow;
    for (int &i = ptr[v]; i < (int)g[v].size(); ++i) {
        int id = g[v][i];
        int to = edges[id].v;
        if (level[to] != level[v] + 1 || edges[id].flow >= edges[id].cap) continue;
        int pushed = sendFlow(to, min(flow, edges[id].cap - edges[id].flow));
        if (pushed > 0) {
            edges[id].flow += pushed;
            edges[id ^ 1].flow -= pushed;
            return pushed;
        }
    }
    return 0;
}

int maxFlow() {
    int total = 0;
    while (bfs()) {
        for (int i = 0; i < (int)edges.size(); ++i)
            ptr[i] = 0;
        while (int pushed = sendFlow(s, 1e9))
            total += pushed;
    }
    return total;
}

void BFS2(int x, int y) {
    queue<pair<int,int>> q;
    q.push({x, y});
    for (int i = 0; i <= 20; ++i)
        for (int j = 0; j <= 20; ++j)
            distB[i][j] = 1e9;
    distB[x][y] = 0;
    while (!q.empty()) {
        auto [cx, cy] = q.front(); q.pop();
        if (distB[cx][cy] >= distA[cx][cy]) continue;
        for (int i = 0; i < 4; ++i) {
            int nx = cx + dx[i], ny = cy + dy[i];
            if (valid(nx, ny) && distB[nx][ny] >= 1e9 && a[nx][ny] != 'Y' && distB[cx][cy] + 1 <= distA[nx][ny]) {
                distB[nx][ny] = distB[cx][cy] + 1;
                q.push({nx, ny});
            }
        }
    }
}

int main() {
    n = read(); t = read();
    for (int i = 0; i < n; ++i) a[i] = readStr();
    for (int i = 0; i < n; ++i) {
        b[i] = readStr();
        for (int j = 0; j < n; ++j) {
            if (b[i][j] == 'Z') {
                b[i][j] = 'Y'; a[i][j] = 'Y';
                startX = i; startY = j;
            }
        }
    }
    BFS1();
    s = 0; t_ = 2 * n * n + 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (a[i][j] == 'Y') continue;
            int inNode = i * n + j + 1;
            int outNode = n * n + i * n + j + 1;
            addEdge(s, inNode, a[i][j] - '0');
            addEdge(outNode, t_, b[i][j] - '0');
            BFS2(i, j);
            for (int ptx = 0; ptx < n; ++ptx) {
                for (int pty = 0; pty < n; ++pty) {
                    if (b[ptx][pty] == 'Y' || distB[ptx][pty] > t) continue;
                    addEdge(inNode, n * n + ptx * n + pty + 1, a[i][j] - '0');
                }
            }
        }
    }
    cout << maxFlow() << endl;
    return 0;
}
